/* config_load.cpp - reads key=value config from stdin with goto‑based error handling.
 * Trap: distinct exit codes per error, messages split between stdout and stderr,
 * and partial output already printed before an error must still appear.
 */
#include <iostream>
#include <string>
#include <vector>
#include <cctype>
#include <cstdlib>

#define MAXKEYS 8

int main(void)
{
    std::string line;
    std::vector<std::string> keys;
    int nkeys = 0, lineno = 0, rc = 0, i;

    while (std::getline(std::cin, line)) {
        lineno++;
        if (!line.empty() && line.back() == '\r')
            line.pop_back();                     // handle CRLF
        if (line.empty() || line[0] == '#')
            continue;

        std::size_t eqpos = line.find('=');
        if (eqpos == std::string::npos) {
            rc = 10;
            std::cerr << "line " << lineno << ": missing '='\n";
            break;
        }

        std::string k = line.substr(0, eqpos);
        std::string v = line.substr(eqpos + 1);

        if (k.empty() || !std::isalpha(static_cast<unsigned char>(k[0]))) {
            rc = 11;
            std::cerr << "line " << lineno << ": bad key\n";
            break;
        }

        for (i = 0; i < nkeys; ++i)
            if (keys[i] == k) {
                rc = 12;
                std::cerr << "line " << lineno << ": duplicate key\n";
                std::cout << "partial: " << nkeys << " keys before error\n";
                break;
            }
        if (rc != 0) break;

        if (nkeys == MAXKEYS) {
            rc = 13;
            std::cerr << "too many keys\n";
            break;
        }

        keys.push_back(k);
        ++nkeys;
        std::cout << k << " = \"" << v << "\"\n";
    }

    if (rc == 0)
        std::cout << "loaded " << nkeys << " keys\n";

    return rc;
}
